 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            # A frame is one connected component forming the complete perimeter
            # of its bounding rectangle.
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                         if y in (r0, r1) or x in (c0, c1)}
            if len(cells) != len(perimeter) or set(cells) != perimeter:
                continue
            interior = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)]
            if not interior or any(grid[y][x] != grid[r0 + 1][c0 + 1] for y, x in interior):
                continue
            fill = 7 if len(interior) % 2 else 2
            for y, x in interior:
                out[y][x] = fill
    return out
